type ConnectionState =
  | { kind: 'disconnected' }
  | { kind: 'connecting'; initiated: string }
  | { kind: 'connected'; sessionId: string };

function describe(state: ConnectionState): string {
  switch (state.kind) {
    case 'disconnected': return 'down';
    case 'connecting':   return `connecting since ${state.initiated}`;
    case 'connected':    return state.sessionId;
    default: return assertNever(state);   // a new variant fails to compile
  }
}
